from __future__ import annotations

from dataclasses import dataclass

DEFAULT_DEVICE = "n150"
DEFAULT_L1_RESERVE_BYTES = 65536
DEFAULT_CB_DEPTH_TILES = 2


@dataclass(frozen=True)
class DeviceSpec:
    """One published device specification, a static planning input."""

    name: str
    arch: str
    compute_grid_x: int
    compute_grid_y: int
    chips: int
    l1_usable_bytes: int
    l1_nominal_bytes: int
    tile_height: int
    tile_width: int
    tile_bytes: int
    clock_hz: int
    flops_per_cycle_per_core: int
    dram_bytes: int
    dram_bandwidth_bytes_per_second: int
    noc_count: int
    noc_flit_bytes: int
    noc_max_burst_bytes: int
    noc_bytes_per_cycle_per_direction: int
    power_watts: int

    @property
    def total_cores(self) -> int:
        """Tensix cores across the board's dies."""
        return self.chips * self.compute_grid_x * self.compute_grid_y

    def cb_budget(self, reserve_bytes: int = DEFAULT_L1_RESERVE_BYTES) -> int:
        """Per-core L1 bytes left for circular buffers after the reserve."""
        return max(0, self.l1_usable_bytes - reserve_bytes)


