def valid_device_names() -> str:
    """Comma-separated device names for error messages."""
    return ", ".join(DEVICES)


def lookup(name: str) -> DeviceSpec:
    """Return the spec for a name or alias; raise KeyError if unknown."""
    if name in DEVICES:
        return DEVICES[name]
    resolved = ALIASES.get(name)
    if resolved is None:
        raise KeyError(f"unknown device {name!r}; valid devices: {valid_device_names()}")
    return DEVICES[resolved]


def all_devices() -> tuple[DeviceSpec, ...]:
    """Every device entry in source order."""
    return tuple(DEVICES.values())
